mapper.select:
SELECT *
FROM INSPECT_DETAIL
WHERE INSPECT_CODE = #{inspectCode}
  AND ASSET_ID = #{assetId}
  AND TARGET_STATUS = 1
ORDER BY TARGET_ITEM

SELECT COUNT(*)
FROM (
         SELECT asset_id, asset_desk
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND asset_desk = #{assetDesk}
         GROUP BY asset_id, asset_desk
     )

SELECT COUNT(*)
FROM (
         SELECT asset_id
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND asset_desk = #{assetDesk}
           AND inspect_state = #{inspectState}
         GROUP BY asset_id
     )

SELECT COUNT(*)
FROM (
         SELECT asset_id
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND inspect_state = #{inspectState}
         GROUP BY asset_id
     )

SELECT inspect_code, asset_id, asset_name, asset_ip1, org_name, room_name, cabinet_name, MAX(inspect_state) inspectState, asset_desk FROM inspect_detail WHERE inspect_code = #{inspectCode} AND asset_desk = #{desks}
AND INSPECT_STATE = #{status}
GROUP BY inspect_code, asset_id, asset_name, asset_ip1, org_name, room_name, cabinet_name, asset_desk ORDER BY asset_desk, asset_id

SELECT ind.id, ind.ASSET_ID AS assetId, -- ai.status AS alarmStatus, ind.ASSET_NAME AS assetName, ind.REMARK AS remarkStr, ind.ALARM_ID AS alarmId, ass.DESK AS assetMode, aet.NAME, ai.TITLE AS alarmTitle, COALESCE(NULLIF(TRIM(ai.DESCRIPTION), ''), ind.result_msg) AS alarmDescription, ai.ALARM_LEVEL AS alarmLevel, ai.STATUS AS solveStatus FROM INSPECT_DETAIL ind LEFT JOIN ALARM_EVENT_TYPE aet ON aet.id = ind.EVENT_TYPE_ID LEFT JOIN ASSET ass ON ass.ID = ind.ASSET_ID LEFT JOIN ALARM_INFO ai ON ai.ID = ind.ALARM_ID WHERE ind.INSPECT_CODE = #{inspectCode}
AND ind.EVENT_TYPE_ID = #{eventTypeId}
AND ind.ALARM_ID IS NOT NULL ORDER BY ind.asset_ip1
